using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace WaterTurn.EditorTools
{
    /// <summary>
    /// Helps hand-author the hub: create one draggable anchor per level, or
    /// snap them back to the layout generated by the default code.
    /// </summary>
    public static class HubAuthoringTools
    {
        const string Menu = "WaterTurn/Hub/";
        const float Cell = 28f;
        const int W = 45, H = 27;

        static readonly Vector2Int[] Cells =
        {
            // 01-04 north-west
            new Vector2Int(5, 8), new Vector2Int(9, 8), new Vector2Int(5, 10), new Vector2Int(9, 10),
            // 05-08 north-east
            new Vector2Int(35, 8), new Vector2Int(39, 8), new Vector2Int(35, 10), new Vector2Int(39, 10),
            // 09-12 centre
            new Vector2Int(20, 15), new Vector2Int(24, 15), new Vector2Int(20, 17), new Vector2Int(24, 17),
            // 13-16 south-west
            new Vector2Int(5, 18), new Vector2Int(9, 18), new Vector2Int(5, 20), new Vector2Int(9, 20),
            // 17-20 south-east
            new Vector2Int(35, 18), new Vector2Int(39, 18), new Vector2Int(35, 20), new Vector2Int(39, 20),
            // hidden
            new Vector2Int(7, 19)
        };

        static readonly Color[] ChapterActive =
        {
            new Color(0.35f, 0.85f, 0.62f, 1f),
            new Color(0.38f, 0.62f, 1f, 1f),
            new Color(0.30f, 0.80f, 0.88f, 1f),
            new Color(0.95f, 0.58f, 0.28f, 1f),
            new Color(0.82f, 0.62f, 1f, 1f),
            new Color(1f, 0.72f, 0.30f, 1f)
        };

        [MenuItem(Menu + "创建关卡入口锚点", false, 20)]
        static void CreateAnchors()
        {
            var hub = Object.FindFirstObjectByType<HubGame>();
            if (hub == null)
            {
                EditorUtility.DisplayDialog("WaterTurn", "请先打开 WaterTurnHub 场景。", "好");
                return;
            }

            var root = hub.transform.Find("Level Entrances");
            if (root != null && root.childCount > 0)
            {
                EditorUtility.DisplayDialog("WaterTurn",
                    "场景里已经有入口锚点了。要重置位置，请用“重置入口锚点位置”。", "好");
                return;
            }

            if (root == null)
            {
                var go = new GameObject("Level Entrances");
                Undo.RegisterCreatedObjectUndo(go, "Create Level Entrances");
                go.transform.SetParent(hub.transform, false);
                root = go.transform;
            }

            for (int i = 0; i < Cells.Length; i++)
            {
                int level = i;
                var anchorObject = new GameObject(level >= Campaign.VisibleLevels
                    ? "Hidden Portal"
                    : "Portal " + (level + 1).ToString("00"));
                Undo.RegisterCreatedObjectUndo(anchorObject, "Create Portal Anchor");
                anchorObject.transform.SetParent(root, false);
                anchorObject.transform.localPosition = MapPosition(Cells[i].x, Cells[i].y);

                var anchor = anchorObject.AddComponent<HubPortalAnchor>();
                anchor.level = level;
                anchor.title = level >= Campaign.VisibleLevels
                    ? "隐藏关"
                    : (level + 1).ToString("00");
                anchor.subtitle = Campaign.Levels[Mathf.Clamp(level, 0, Campaign.Levels.Length - 1)].Name;
                var color = ChapterActive[Mathf.Clamp(Campaign.Chapter(level), 0, ChapterActive.Length - 1)];
                anchor.activeColor = color;
                anchor.haloColor = color;
                anchor.compact = true;
            }

            EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
            Selection.activeGameObject = root.gameObject;
            Debug.Log("WaterTurn: 已创建 " + Cells.Length + " 个可拖动入口锚点。");
        }

        [MenuItem(Menu + "重置入口锚点位置", false, 21)]
        static void ResetAnchors()
        {
            var anchors = Object.FindObjectsByType<HubPortalAnchor>(
                FindObjectsInactive.Include, FindObjectsSortMode.None);
            if (anchors.Length == 0)
            {
                EditorUtility.DisplayDialog("WaterTurn", "场景里没有入口锚点。", "好");
                return;
            }

            foreach (var anchor in anchors)
            {
                int level = Mathf.Clamp(anchor.level, 0, Cells.Length - 1);
                Undo.RecordObject(anchor.transform, "Reset Portal Anchor");
                anchor.transform.localPosition = MapPosition(Cells[level].x, Cells[level].y);
            }
            EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
            Debug.Log("WaterTurn: 已把入口锚点重置到默认布局。");
        }

        [MenuItem(Menu + "删除关卡入口锚点", false, 22)]
        static void DeleteAnchors()
        {
            var anchors = Object.FindObjectsByType<HubPortalAnchor>(
                FindObjectsInactive.Include, FindObjectsSortMode.None);
            if (anchors.Length == 0) return;
            if (!EditorUtility.DisplayDialog("WaterTurn",
                    "删除场景里全部 " + anchors.Length + " 个入口锚点？", "删除", "取消"))
                return;

            var seen = new HashSet<GameObject>();
            foreach (var anchor in anchors)
            {
                if (anchor != null && seen.Add(anchor.gameObject))
                    Undo.DestroyObjectImmediate(anchor.gameObject);
            }
            EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
        }

        static Vector2 MapPosition(int x, int y)
        {
            return new Vector2((x - (W - 1) * .5f) * Cell, ((H - 1) * .5f - y) * Cell);
        }
    }
}
